SELECT lr.login_id, r.role_id, r.role_code, r.role_nm FROM tb_login_account_role lr JOIN tb_login_account la ON la.login_id = lr.login_id JOIN tb_role r ON r.role_id = lr.role_id AND r.tenant_id = la.tenant_id WHERE la.tenant_id = #{tenantId}
AND lr.login_id = #{loginId}
ORDER BY lr.login_id, r.role_id

