mapper.update:
UPDATE tb_login_account
SET use_at = #{useAt},
    updated_at = now(),
    updated_by = #{actorUserId}
WHERE tenant_id = #{tenantId}
  AND login_id = #{loginId}

UPDATE tb_login_account
SET password_hash = #{passwordHash},
    password_change_required = 'Y',
    login_attempt_count = 0,
    locked_at = NULL,
    updated_at = now(),
    updated_by = #{actorUserId}
WHERE tenant_id = #{tenantId}
  AND login_id = #{loginId}

UPDATE tb_login_account
SET login_attempt_count = 0,
