  AND login_id = #{loginId}

mapper.delete:
DELETE FROM tb_login_account_role
WHERE login_id = #{loginId}
  AND login_id IN (
      SELECT login_id FROM tb_login_account WHERE tenant_id = #{tenantId}
  )
